<script setup>
import {ref} from 'vue';import {session,request} from './api'
const question=ref(''),rule=ref(''),lot=ref(''),thread=ref(''),proposal=ref(''),graphEnd=ref(''),autonomy=ref(1),draft=ref('')
async function run(){const r=await request('/api/agent/run',{profile:session.profile,source_id:session.source,rule_id:rule.value,lot_id:lot.value||null,question:question.value,provider:session.provider,graph_end:graphEnd.value,autonomy:autonomy.value});if(r.status==='pending_approval'){thread.value=r.answer.thread_id;proposal.value=r.answer.proposal.id;draft.value=r.answer.draft_set?.id||''}else if(r.answer?.drafts){draft.value=r.answer.id}}
</script>
<template><section class="panel"><p class="eyebrow">이벤트 → 관계 → 문서 → 검토안 → 재생</p><h2>기록이 다음 판단을 바꾸게 합니다</h2><label>판단할 질문<textarea v-model="question"/></label><div class="form-row"><label>현재 상대 규칙 ID<input v-model="rule" placeholder="cushion-relative"/></label><label>LOT 범위<input v-model="lot"/></label><label>관계의 끝 대상 ID<input v-model="graphEnd" placeholder="관계 화면에서 확인한 ID"/></label></div><label>이번 실행의 권한<select v-model.number="autonomy"><option :value="0">0 · 근거 조회</option><option :value="1">1 · 세 종류의 초안 작성</option><option :value="2">2 · 규칙 변경을 사람 승인에 연결</option></select></label><button class="primary" @click="run" :disabled="session.busy||!rule||!question||!lot||!graphEnd">선택한 범위로 진행</button><fieldset><legend>방금 초안에서 이어 보기</legend><label>초안 묶음 번호<input v-model="draft"/></label><button :disabled="session.busy||!draft" @click="request('/api/agent/drafts/'+encodeURIComponent(draft)+'?kind=first_inspection')">초물검사만 보기</button><button :disabled="session.busy||!draft" @click="request('/api/agent/drafts/'+encodeURIComponent(draft)+'?kind=four_m')">4M 신고 초안 보기</button><button :disabled="session.busy||!draft" @click="request('/api/agent/drafts/'+encodeURIComponent(draft)+'/8d')">관측·결정을 8D로 읽기</button></fieldset><fieldset><legend>사람의 결정 이후</legend><label>작업 번호<input v-model="thread"/></label><label>승인 대기 제안 번호<input v-model="proposal"/></label><button :disabled="session.busy||!thread||!proposal" @click="request('/api/agent/resume',{thread_id:thread,proposal_id:proposal})">저장된 결정으로 이어가기</button></fieldset><p class="muted">조회와 초안, 승인된 소프트웨어 규칙 변경을 구분합니다. 초물검사·4M 문안은 검토 초안이며 실제 검사·신고를 수행한 기록이 아닙니다.</p></section></template>
